Using Convex 1.44.0, these are the complete handlers. They contain no authentication checks.

```ts
import { query, mutation, action, internalQuery, internalMutation, internalAction } from "./_generated/server";
export const publicQuery = query({ args: {}, handler: async () => null });
export const publicMutation = mutation({ args: {}, handler: async () => null });
export const publicAction = action({ args: {}, handler: async () => null });
export const privateQuery = internalQuery({ args: {}, handler: async () => null });
export const privateMutation = internalMutation({ args: {}, handler: async () => null });
export const privateAction = internalAction({ args: {}, handler: async () => null });
```
